"""New Codex-authored scenarios. Split groups assigned before authoring. No old corpus mutation."""
TRAIN=[];DEV=[]
def add(split,family,group,*turns):
 assert 3<=len(turns)<=6
 (TRAIN if split=='train' else DEV).append((group,family,turns))
# Ordinary exchanges: respond to the person, do not manufacture a user turn.
add('train','ordinary','weekend_rest',('I finally have a quiet weekend.','That sounds like a welcome chance to slow down.'),('I do not want to make any plans.','You can leave the weekend open and decide as you go.'),('That is what I needed to hear.','Enjoy the breathing room.'))
add('train','ordinary','small_success',('I finished sorting a cupboard that I kept putting off.','It must feel good to have that task finished.'),('It does. There is one more, but not today.','The other cupboard can wait. You have finished this one.'),('Give me a short reminder for tomorrow.','Sort the remaining cupboard tomorrow.'))
add('train','ordinary','missed_friend',('I miss a friend who moved away.','Being far apart can be hard. Would you like help writing a message?'),('Yes, something simple and not dramatic.','I was thinking of you today. How have you been?'),('Add that I would like to catch up.','I was thinking of you today. How have you been? I would love to catch up.'))
add('train','ordinary','quiet_company',('I have had a tiring afternoon.','That sounds draining. Would you prefer to talk about it or take your mind off it?'),('Take my mind off it. Ask me about something pleasant.','What is a small thing you have enjoyed recently?'),('Listening to rain while I was indoors.','That sounds peaceful, especially when you can stay dry and comfortable.'))
add('train','ordinary','thanks_help',('Thanks for helping me organise my notes.','You are welcome.'),('I can find things much faster now.','It sounds like the new arrangement is working for you.'),('Keep your next reply to one short sentence.','I am glad it is helping.'))
add('train','ordinary','hobby_start',('I want to try drawing but I am not very good at it.','You can start with something simple, such as a cup or a leaf, and practise observing its shape.'),('I have a cup beside me.','Try sketching its outline first, then add the handle.'),('I will try that now.','Take your time with it.'))
# Clarification: ask only for missing information, then use the answer.
add('train','clarification','message_recipient',('Help me write a message about a change of plan.','Who is the message for, and what changed?'),('For my cousin. I will arrive tomorrow instead of tonight.','I will arrive tomorrow instead of tonight. Sorry for the change of plan.'),('Make it more casual.','Change of plan: I will get there tomorrow, not tonight. Sorry about that!'))
add('train','clarification','choice_scope',('Which one should I choose?','What are the options, and what matters most to you?'),('A small bag or a large bag. I only need to carry a notebook.','The small bag sounds sufficient if the notebook fits.'),('It fits with room to spare.','Then I would choose the small bag.'))
add('train','clarification','ambiguous_pronoun',('Nadia called Farid after they left. Who left?','The sentence is ambiguous: "they" could refer to Nadia, Farid, or both of them.'),('I meant Farid. Rewrite it clearly.','After Farid left, Nadia called him.'),('Who made the call?','Nadia made the call.'))
add('train','clarification','editing_missing',('Can you make this shorter?','Please send the text you would like shortened.'),('I am writing to let you know that I cannot attend the gathering this evening.','I cannot attend the gathering this evening.'),('Keep the apology too: I am sorry.','I am sorry, but I cannot attend the gathering this evening.'))
add('train','clarification','reminder_detail',('Write a reminder for me to return something.','What do you need to return, and when?'),('A library book, next Wednesday.','Return the library book next Wednesday.'),('Did you set a reminder on my phone?','No. I wrote the reminder text; I did not set anything on your phone.'))
add('train','clarification','unclear_location',('Put it over there.','What object do you mean, and where should it go?'),('I mean the spare cushion, on the armchair. I just need a written instruction.','Put the spare cushion on the armchair.'),('Use a polite tone.','Please put the spare cushion on the armchair.'))
# Exact instructions: content and formatting both matter.
add('train','instructions','single_word',('Reply with only the word noted.','noted'),('Now write that word in uppercase, with nothing else.','NOTED'),('Return it to lowercase. No punctuation.','noted'))
add('train','instructions','word_order',('Write only these words in order, separated by a space: red blue.','red blue'),('Reverse their order. Keep the same format.','blue red'),('Give only the first word in your last answer.','blue'))
add('train','instructions','list_format',('List cup and plate on separate lines, without bullets.','cup\nplate'),('Put those items on one line, separated by a comma and a space.','cup, plate'),('Remove the cup. Give only the remaining item.','plate'))
add('train','instructions','punctuation',('Write only the word welcome followed by a full stop.','welcome.'),('Replace the full stop with a question mark.','welcome?'),('Remove the punctuation.','welcome'))
add('train','instructions','position',('From tulip, fern, moss, give only the last item.','moss'),('Now give only the middle item from that same list.','fern'),('Give only the first item.','tulip'))
add('train','instructions','length_constraint',('Answer in exactly two words: say that you understand.','I understand'),('Now acknowledge using exactly one word.','Understood'),('Write that same word twice, separated by one space.','Understood Understood'))
# Grounding: known and unknown must not be conflated.
add('train','grounding','ticket_price',('The notice says tickets are available, but gives no price. How much is a ticket?','The price is not given in the notice.'),('The organiser now says each ticket costs twelve rupees. What is the price?','Twelve rupees per ticket.'),('Does that tell us how many tickets remain?','No. The number of tickets remaining is still unknown.'))
add('train','grounding','book_author',('I found a book with a blue cover. Who wrote it?','A blue cover is not enough information to identify its author.'),('The title page lists the author as Kavya Sen.','Then the listed author is Kavya Sen.'),('Where was Kavya born?','That information has not been provided.'))
add('train','grounding','weather_evidence',('My neighbour is carrying an umbrella. Is it raining outside?','The umbrella alone does not tell us whether it is raining.'),('I just looked outside and saw rain falling.','Your observation confirms that it is raining where you looked.'),('Will it rain tomorrow too?','That observation does not establish tomorrow\'s weather.'))
add('train','grounding','empty_label',('A jar has no label and I cannot see inside it. What is in it?','There is not enough information to know what is inside.'),('I opened it and found lentils.','The jar contains lentils.'),('Can we tell when they were put there?','No. Opening the jar does not tell us when the lentils were put there.'))
add('train','grounding','arrival_unknown',('Saira said she would visit today. She did not give a time. When will she arrive?','We do not know the arrival time.'),('She has now said she will arrive at noon.','Her stated arrival time is noon.'),('Has she arrived already?','I do not have information confirming that she has arrived.'))
add('train','grounding','no_action_claim',('Please tell my brother that dinner is ready.','I can draft the message, but I cannot send it to your brother here.'),('Just give me the message.','Dinner is ready.'),('Did he receive it?','I did not send it, so I cannot confirm that he received it.'))
# Entity roles, exclusions and relations.
add('train','entity','borrowed_camera',('Sonal owns a camera. Arman borrowed it. Who owns the camera?','Sonal owns it.'),('Who borrowed it?','Arman borrowed it.'),('Arman has returned it. Does that change who owns it?','No. Sonal still owns the camera.'))
add('train','entity','two_tasks',('Deepa waters the plants. Yusuf sweeps the steps. Who waters the plants?','Deepa waters the plants.'),('What does Yusuf do?','Yusuf sweeps the steps.'),('Who sweeps the steps?','Yusuf.'))
add('train','entity','different_containers',('The tin holds pins. The pouch holds ribbons. Where are the ribbons?','In the pouch.'),('What is in the tin?','Pins.'),('Does that description say the tin holds ribbons?','No. It says the tin holds pins.'))
add('train','entity','sender_receiver',('Uma sent a postcard to Joel. Who received the postcard?','Joel received it.'),('Who sent it?','Uma sent it.'),('Joel sent a reply to Uma. Who received the reply?','Uma received the reply.'))
add('train','entity','included_excluded',('The basket contains lemons, but no oranges. Which fruit is included?','Lemons are included.'),('Are oranges included?','No, oranges are not included.'),('Name only the fruit that is present.','lemons'))
add('train','entity','desk_positions',('The stapler is beside the monitor. The ruler is inside the drawer. What is inside the drawer?','The ruler.'),('Where is the stapler?','Beside the monitor.'),('Is the stapler inside the drawer?','No. It is beside the monitor.'))
# Corrections: obsolete value must not remain active.
add('train','correction','pickup_hour',('My pickup is at ten. Please keep that in mind.','Got it: your pickup is at ten.'),('It has changed to eleven.','Your pickup is now at eleven.'),('What time should I use now?','Eleven.'))
add('train','correction','shirt_colour',('I selected the grey shirt.','You selected the grey shirt.'),('Actually, switch my choice to the white shirt.','Your choice is now the white shirt.'),('Which colour did I settle on?','White.'))
add('train','correction','meeting_room',('The discussion will be in Room A.','The discussion is in Room A.'),('Room A is unavailable. Move it to Room C.','The discussion is now in Room C.'),('Where is the discussion taking place?','Room C.'))
add('train','correction','contact_spelling',('The contact name is Alia.','The contact name is Alia.'),('I misspelled it. Use Aaliya instead.','The corrected name is Aaliya.'),('Give the corrected name only.','Aaliya'))
add('train','correction','container_move',('I left the envelope on the shelf.','The envelope is on the shelf.'),('I have moved it to the desk.','The envelope is now on the desk.'),('Where should I look for it now?','On the desk.'))
add('train','correction','cancelled_plan',('We are visiting the park this afternoon.','You plan to visit the park this afternoon.'),('Cancel that. We are staying home instead.','The park visit is cancelled; you are staying home.'),('Are we still going to the park?','No. You are staying home instead.'))
# Memory amid an intervening topic; no long-context claim.
add('train','memory','seat_preference',('I prefer an aisle seat. Please remember that for this conversation.','You prefer an aisle seat.'),('I will be carrying a small backpack.','You will be carrying a small backpack.'),('What kind of seat did I say I prefer?','An aisle seat.'))
add('train','memory','plant_name',('I named my plant Sprout.','Your plant is named Sprout.'),('Its pot is by the kitchen window.','The pot is by the kitchen window.'),('What name did I give the plant?','Sprout.'))
add('train','memory','spare_key',('The spare key is in the ceramic bowl.','The spare key is in the ceramic bowl.'),('There is a scarf hanging by the door.','There is a scarf by the door.'),('Where did I say the spare key was?','In the ceramic bowl.'))
add('train','memory','picnic_item',('I will bring napkins to the picnic.','You will bring napkins.'),('Someone else is arranging transport.','Transport is being arranged by someone else.'),('What am I bringing?','Napkins.'))
add('train','memory','preferred_contact',('Please use email rather than calling when drafting contact instructions for me.','Your preferred contact method is email.'),('My office is upstairs.','Your office is upstairs.'),('Which contact method did I prefer?','Email.'))
add('train','memory','corrected_then_distracted',('The workshop is in the morning.','The workshop is in the morning.'),('Move it to the evening. Also, the entrance has a red sign.','The workshop is now in the evening, and the entrance has a red sign.'),('When is the workshop now?','In the evening.'))
# Rewriting: perform the edit, preserve facts, don't append imagined context.
add('train','rewrite','short_notice',('Shorten this: I would like to inform you that the gate will close at dusk.','The gate will close at dusk.'),('Make it a polite reminder.','Please remember that the gate will close at dusk.'),('What time does the notice specify?','Dusk.'))
add('train','rewrite','polite_request',('Make this polite: Pass the towel.','Could you please pass the towel?'),('Keep it polite but shorter.','Please pass the towel.'),('Change towel to blanket.','Please pass the blanket.'))
add('train','rewrite','preserve_negative',('Simplify this: The parcel has not yet arrived.','The parcel has not arrived yet.'),('Make it even shorter without saying it arrived.','The parcel has not arrived.'),('Has it arrived according to the sentence?','No.'))
add('train','rewrite','apology_text',('Write a brief apology for forgetting to return a pencil. Do not add an excuse.','I am sorry I forgot to return your pencil.'),('Add that I will return it tomorrow.','I am sorry I forgot to return your pencil. I will return it tomorrow.'),('Remove the apology and keep only the promise.','I will return your pencil tomorrow.'))
add('train','rewrite','summary_facts',('Summarise in one sentence: A tap leaked. Mina tightened it. The leak stopped.','Mina stopped the leak by tightening the tap.'),('Who tightened the tap?','Mina.'),('Rewrite the summary without the person\'s name.','The leak stopped after the tap was tightened.'))
add('train','rewrite','invitation_tone',('Make this invitation warmer without adding details: Come for lunch.','We would love to have you over for lunch.'),('Make it less formal.','Come over for lunch; we would love to see you.'),('Change lunch to dinner.','Come over for dinner; we would love to see you.'))
# Development: distinct situations and request structures; shared capabilities are deliberate.
add('development','ordinary','dev_finished_puzzle',('The puzzle I was working on is finally complete.','Finishing it must feel satisfying.'),('I want to leave it out for a while.','You can enjoy seeing the finished puzzle before putting it away.'),('No advice now, just a brief response.','Enjoy it.'))
add('development','ordinary','dev_waiting',('I am bored while waiting for a friend.','Would you like a small distraction while you wait?'),('Ask me an easy question about my day.','What was the most pleasant part of your day so far?'),('Having breakfast outside.','That sounds like a pleasant start to the day.'))
add('development','ordinary','dev_reassurance',('I tried a new recipe and it did not turn out as I hoped.','That is frustrating after putting in the effort.'),('I do not want troubleshooting.','Understood. We do not need to troubleshoot it.'),('Thanks for listening.','You are welcome.'))
add('development','clarification','dev_ambiguous_comparison',('Is this better than the other one?','Which two things are you comparing, and what would make one better for you?'),('Two reading lamps. Only one has an adjustable arm, and I need to direct the light.','The lamp with the adjustable arm sounds better suited to that need.'),('Which feature mattered?','The adjustable arm, because you want to direct the light.'))
add('development','clarification','dev_missing_sentence',('Please fix the grammar.','Please send the sentence you want corrected.'),('She carry the boxes.','She carries the boxes.'),('Make it past tense.','She carried the boxes.'))
add('development','clarification','dev_unclear_they',('Nina met the twins when they returned. Who returned?','In that sentence, "they" most naturally refers to the twins.'),('Change it so Nina is the one who returned.','When Nina returned, she met the twins.'),('Who returned in the revised sentence?','Nina.'))
add('development','instructions','dev_brackets',('Output only the word done inside square brackets.','[done]'),('Use round brackets instead.','(done)'),('Remove the brackets and capitalise the first letter.','Done'))
add('development','instructions','dev_separator',('Write ant and bee separated by a slash. No other text.','ant/bee'),('Replace the slash with a hyphen.','ant-bee'),('Now give only the word after the hyphen.','bee'))
add('development','instructions','dev_select_phrase',('Reply with the last word of "a gentle breeze" and nothing else.','breeze'),('Give the first word of that original phrase.','a'),('Give the middle word only.','gentle'))
add('development','grounding','dev_birthplace',('All I know about Rehan is that he repairs clocks. Where was he born?','His birthplace cannot be determined from that information.'),('He says he was born in Patna.','His stated birthplace is Patna.'),('Do we know where he lives now?','No. His current home has not been specified.'))
add('development','grounding','dev_shop_hours',('A sign says the shop is open on holidays. What time does it close?','The sign does not give a closing time.'),('Another sign says it closes at six in the evening.','The stated closing time is six in the evening.'),('Does that tell us when it opens?','No. The opening time is still unspecified.'))
add('development','grounding','dev_missing_size',('A listing calls a table wooden but gives no measurements. Will it fit through my doorway?','We need the table dimensions and doorway measurements to determine that.'),('Can you confidently say yes without those measurements?','No. There is not enough information to say that confidently.'),('Give me a short request to send the seller.','Could you please provide the table dimensions?'))
add('development','entity','dev_team_roles',('At rehearsal, Pablo handles lighting and Mira handles costumes. Who handles costumes?','Mira handles costumes.'),('Who handles lighting?','Pablo.'),('Does Pablo handle costumes according to that description?','No. Mira handles costumes.'))
add('development','entity','dev_map_symbols',('On this map, a star marks the station and a circle marks the clinic. What does the circle mark?','The clinic.'),('Which symbol marks the station?','A star.'),('Does the star mark the clinic?','No. It marks the station.'))
add('development','entity','dev_absent_item',('The drawer has scissors and tape, but no glue. Is there glue in the drawer?','No, there is no glue in the drawer.'),('Name the two items that are there.','Scissors and tape.'),('Which adhesive item is present?','Tape.'))
add('development','correction','dev_return_day',('I will return the board game on Thursday.','You will return it on Thursday.'),('That no longer works; make it Friday.','The return day is now Friday.'),('Which day is the return planned for now?','Friday.'))
add('development','correction','dev_active_contact',('The caretaker to contact is Ravi.','Ravi is the caretaker to contact.'),('Ravi is away. Contact Lila instead.','Lila is now the contact.'),('Whom should I contact under the revised plan?','Lila.'))
add('development','correction','dev_storage_change',('The torch is in the cabinet.','The torch is in the cabinet.'),('I have taken it out and put it in the basket.','The torch is now in the basket.'),('Where can I find the torch now?','In the basket.'))
add('development','memory','dev_favourite_sound',('My favourite sound is waves on the shore.','Your favourite sound is waves on the shore.'),('My desk faces a wall, and there is a clock above it.','Your desk faces a wall with a clock above it.'),('What sound did I say I like most?','Waves on the shore.'))
add('development','memory','dev_carried_item',('For the visit, I am bringing a sketchbook.','You are bringing a sketchbook.'),('The building has a side entrance.','The building has a side entrance.'),('What did I say I would bring?','A sketchbook.'))
add('development','memory','dev_revised_route',('We plan to take the tunnel.','You plan to take the tunnel.'),('Use the bridge instead. The weather forecast is clear.','You will use the bridge instead, and the forecast is clear.'),('Which route did we settle on?','The bridge.'))
add('development','rewrite','dev_remove_filler',('Remove unnecessary words: At this point in time, the lift is not working.','The lift is not working.'),('Add a polite request to use the stairs.','The lift is not working. Please use the stairs.'),('Keep only the request.','Please use the stairs.'))
add('development','rewrite','dev_preserve_order',('Say this more simply: Prior to leaving, ensure that the window is shut.','Close the window before leaving.'),('Change it to happen after leaving, keeping the other action.','Close the window after leaving.'),('In the revised sentence, which happens first?','Leaving happens first.'))
add('development','rewrite','dev_condense_update',('Make this shorter without losing facts: The bus was late, and as a result we arrived after the start.','The late bus made us miss the start.'),('Do not imply that we missed the whole event.','The bus was late, so we arrived after the event began.'),('What caused the late arrival?','The bus was late.'))

# Longer exchanges: vary speech acts and response lengths rather than multiply short templates.
add('train','ordinary','uneasy_new_group',('I joined a reading group but felt awkward at the first meeting.','A first meeting can feel awkward when everyone is unfamiliar. You do not have to become comfortable immediately. What part felt hardest?'),('Starting a conversation before the discussion began.','You could start with the shared reason you are there: ask what someone thought of the book, or whether they have been to the group before. A small opening is enough.'),('Give me one line I could actually say.','Is this your first time at this reading group?'),('Make it less like a yes-or-no question.','What brought you to this reading group?'))
add('train','ordinary','unfinished_project',('I started making a photo album and lost interest halfway through.','You can leave it unfinished for now. If you want to return to it, a smaller stopping point may feel easier than completing the whole album.'),('I do want to finish, but I only have energy for a little.','Choose a small section, such as one page or one occasion, and work only on that. You can stop when that section is done.'),('One page sounds manageable. Do not give me a longer plan.','Then make one page your goal for now.'),('What did we settle on?','Working on one page of the photo album.'))
add('train','clarification','busy_day',('Help me decide what to do first today.','What tasks are on your list, and does anything have a fixed deadline?'),('Wash some dishes, reply to an invitation by noon, and arrange a shelf.','Reply to the invitation first because it has a deadline. The dishes and shelf can come afterward.'),('The invitation reply is now done. What next?','You could wash the dishes next, then arrange the shelf.'),('I want the shelf before the dishes.','Then arrange the shelf next and leave the dishes until afterward.'))
add('train','clarification','tone_for_note',('I need a note for someone who keeps leaving things in the hallway.','Should the note sound friendly, firm, or neutral? Is there a particular item you want mentioned?'),('Friendly. Mention shoes, and ask that the walkway stay clear.','Could you please keep your shoes out of the walkway? It would help us keep the hallway clear. Thanks.'),('Avoid sounding as though I am blaming a particular person.','Please keep shoes out of the walkway so the hallway stays clear. Thank you.'),('Give it a short heading.','Please keep the hallway clear'))
add('train','instructions','bounded_suggestions',('Suggest two quiet indoor activities. No screens and no exercise.','You could read a book or draw on paper.'),('I do not have paper. Replace drawing with something that needs none.','You could read a book or listen to quiet music.'),('Give only the second activity, without an explanation.','Listen to quiet music.'),('Now put that activity in lowercase, without the full stop.','listen to quiet music'))
add('train','instructions','precise_edit',('Write one sentence asking for the document by tonight. Do not apologise.','Please send the document by tonight.'),('Change the deadline to tomorrow morning. Keep everything else.','Please send the document by tomorrow morning.'),('Remove the word please and start with a capital letter.','Send the document by tomorrow morning.'),('What is the current deadline? Give only the deadline.','tomorrow morning'))
add('train','grounding','partial_story',('A woman rushed out carrying a bag. Was she catching a train?','The description does not say why she rushed out. Catching a train is one possibility, but it would be a guess.'),('A later sentence says she was going to meet her daughter.','Then meeting her daughter is the stated reason for leaving.'),('Does that tell us whether she used a train to get there?','No. Her reason for leaving does not establish how she travelled.'),('Summarise only what is known.','She rushed out carrying a bag to meet her daughter.'))
add('train','grounding','reported_vs_verified',('My friend says the community hall will reopen next week. Can you confirm that?','I cannot independently confirm it here. Based on what you shared, reopening next week is your friend\'s report.'),('Help me write a question to the caretaker instead.','Could you please confirm whether the community hall will reopen next week?'),('Make it shorter.','Will the community hall reopen next week?'),('Did we establish the reopening date?','No. We drafted a question; we have not received confirmation.'))
add('train','entity','three_person_exchange',('Aditi handed a parcel to Leon, who passed it to Mei. Who has it at the end?','Mei has the parcel at the end.'),('Who first handed it over?','Aditi.'),('Leon did not keep it. Explain that briefly.','Leon passed the parcel to Mei, so he was not the final holder.'),('Now Mei returns it to Aditi. Who has it?','Aditi.'))
add('train','entity','two_messages',('The gardener asked the driver for a bucket. The driver asked the cook for a towel. Who was asked for a towel?','The cook was asked for a towel.'),('What did the gardener ask for?','A bucket.'),('Did the cook ask the gardener for a bucket?','No. The gardener asked the driver for a bucket.'),('Describe the two requests in one sentence.','The gardener asked the driver for a bucket, and the driver asked the cook for a towel.'))
add('train','correction','changing_constraints',('Draft a notice: the practice is indoors and starts at four.','Practice will be indoors and will start at four.'),('It will be outdoors instead. Keep the time.','Practice will be outdoors and will start at four.'),('Now change the time to five, keeping the new location.','Practice will be outdoors and will start at five.'),('List the current location and time only.','Outdoors, five.'))
add('train','correction','partial_correction',('My lunch order is soup and bread.','Your lunch order is soup and bread.'),('Replace only the soup with salad.','Your order is now salad and bread.'),('The bread stays, right?','Yes. The bread stays in the order.'),('What is my full order now?','Salad and bread.'))
add('train','memory','two_preferences',('For this conversation, remember that I prefer brief replies and dislike surprise endings in stories.','You prefer brief replies and stories without surprise endings.'),('Could we talk about hobbies instead of stories?','Yes. Which hobbies interest you?'),('Gardening. But first, what reply length did I ask for?','Brief replies.'),('And what did I say about story endings?','You dislike surprise endings.'))
add('train','memory','distractor_correction',('My reusable bottle is in the tote bag.','Your reusable bottle is in the tote bag.'),('I moved my umbrella from the tote bag to the cupboard.','Your umbrella is now in the cupboard.'),('Did that change where my bottle is?','No. You only described moving the umbrella.'),('Where is the bottle according to what I told you?','In the tote bag.'))
add('train','rewrite','maintain_uncertainty',('Rewrite this more clearly: It is possible, but not certain, that the parcel will arrive today.','The parcel may arrive today, but it is not certain.'),('Make it shorter while keeping the uncertainty.','The parcel might arrive today.'),('Would "The parcel will arrive today" mean the same thing?','No. That wording presents the arrival as certain rather than possible.'),('Give me the shorter uncertain version again.','The parcel might arrive today.'))
add('train','rewrite','condense_without_invention',('Summarise: I visited the workshop. It was closed. I left a note and went home.','I found the workshop closed, left a note and went home.'),('Can you include why it was closed?','The original text does not say why it was closed.'),('Then keep that detail out and make the summary shorter.','The workshop was closed, so I left a note and went home.'),('Did I meet anyone there?','The text does not say that you met anyone.'))
add('development','ordinary','dev_low_pressure',('I planted some seeds and keep checking whether they have grown.','Waiting for something you planted can make you eager to see progress.'),('I just wanted to share that, not get instructions.','Thanks for sharing it with me.'),('What was I checking?','Whether the seeds had grown.'),('Respond in one short sentence now.','I hope you enjoy watching them grow.'))
add('development','clarification','dev_priority_change',('Can you make it lighter?','Do you mean lighter in weight, colour, or tone?'),('I mean the tone of a message. Here it is: Your delay has caused considerable inconvenience.','The delay has made things difficult.'),('Ask for an update without sounding angry.','Could you please let me know when to expect an update?'),('Was I asking about the weight of an object?','No. You were asking about the tone of a message.'))
add('development','instructions','dev_excluded_topic',('The reference is ZX-41. Return only the two letters before the hyphen.','ZX'),('Now give only the two digits after the hyphen.','41'),('Restore the full reference, keeping its original case and punctuation.','ZX-41'),('Give the full reference in lowercase. Nothing else.','zx-41'))
add('development','grounding','dev_rumour',('Two notes disagree: one says the package is heavy and the other says it is light. Neither is marked newer. Which should I trust?','Those notes alone do not establish which description is correct.'),('The sender confirms the heavy label was an error.','Then the heavy label should not be relied on.'),('Does that confirmation alone give the exact weight?','No. It gives no exact weight.'),('Write a short request for the missing measurement.','Could you please provide the package weight?'))
